from os import popen
import re


def get_vm_user():
    """
    Return the actual user name of UTE VM

    :return: user name
    :rtype: str
    """
    whoami_cmd = popen('/usr/bin/whoami')
    username = whoami_cmd.read()
    return username.strip()


def get_vm_password():
    """
    Return the access password of UTE VM

    :return: password
    :rtype: str
    """
    # assert password is the same as username
    return get_vm_user()


def get_vm_test_logs_dir():
    """
    Return path to the log directory of current test.
    :return: password
    :rtype: str
    """
    from ute_common_abstract_core import logger as core_logger
    return core_logger.logging_path


def get_vm_ssh_port():
    """
    Return the port of ssh service of UTE VM
    :return: port
    :rtype: int
    """
    return 22


def get_vm_ip_address(ifname):
    """
    Return the IP address as string of UTE VM on given interface.

    :param ifname: interface name
    :type ifname: str
    :return: IP address
    :rtype: str
    """
    ipaddr_cmd = popen("ip addr show {} ".format(ifname) + r"| grep -e 'inet\s' | awk '{print $2}' | cut -d/ -f1")
    ip_addr = ipaddr_cmd.read()
    return ip_addr.strip()


def parse_version(version):
    """
    Return parsed version from string "x.x.x"

    :param version: 3-segment version comma separated eg "1.22.123"
    :type version: str
    :return: parsed version
    :rtype: tuple of ints
    """
    try:
        match = re.match(r"^(\d+)\.(\d+)\.(\d+)$", version)
        if match:
            return int(match.group(1)), int(match.group(2)), int(match.group(3))
        else:
            raise ValueError()
    except (ValueError, TypeError) as e:
        raise type(e)("Could not parse version")


def compare_versions(version1, version2):
    """
    Return 1 if version
    :param version1: 3-segment version comma separated eg "1.22.123"
    :type version1: str
    :param version2: 3-segment version comma separated eg "1.22.123"
    :type version2: str
    :return: True if version1 >= version2, False if version1 < version2,
    :rtype: bool
    """
    ver1 = parse_version(version1)
    ver2 = parse_version(version2)

    if ver1 >= ver2:
        return True
    else:
        return False
